const internetContent = `
<h4 id="notes_title">What is Internet?</h4>

<div class="notes_text" id="notes_text">

    <p>
        The Internet is one of the greatest inventions in the field of information technology. Today, it has become an
        essential part of our daily life. We use the Internet for communication, education, business, entertainment,
        banking, shopping, and many other activities.
    </p>

    <p>
        Before understanding Internet services, we should first understand what the Internet is and how it works.
    </p>

    <h3>What is the Internet?</h3>

    <p>
        The <strong>Internet</strong> is a worldwide network of interconnected computers and devices that communicate
        with each other using standard communication protocols such as <strong>TCP/IP (Transmission Control
        Protocol/Internet Protocol)</strong>. It allows users to share information, exchange data, and access various
        online services from anywhere in the world.
    </p>

    <p>
        In simple words, the Internet is a <strong>"Network of Networks"</strong> because it connects millions of
        private, public, educational, business, and government networks together.
    </p>

    <h3>Definitions of Internet</h3>

    <p><strong>Definition 1:</strong></p>

    <p>
        The Internet is a global network that connects millions of computers and devices to enable communication and
        information sharing.
    </p>

    <p><strong>Definition 2:</strong></p>

    <p>
        The Internet is a worldwide system of interconnected computer networks that uses the TCP/IP protocol suite to
        exchange data between devices.
    </p>

    <h3>Why is it Called a "Network of Networks"?</h3>

    <p>
        A network is a group of computers connected together. The Internet connects millions of such networks across
        the world. Since many individual networks are interconnected, the Internet is called a
        <strong>Network of Networks</strong>.
    </p>

    <h3>Basic Components of the Internet</h3>

    <ul>
        <li>Computers and Smart Devices</li>
        <li>Servers</li>
        <li>Routers and Switches</li>
        <li>Communication Media (Fiber, Cable, Satellite, Wireless)</li>
        <li>Internet Service Providers (ISP)</li>
        <li>TCP/IP Communication Protocol</li>
    </ul>

    <h3>Features of the Internet</h3>

    <ul>
        <li>Global Connectivity</li>
        <li>Fast Communication</li>
        <li>Information Sharing</li>
        <li>24×7 Availability</li>
        <li>Resource Sharing</li>
        <li>Supports Multimedia (Text, Images, Audio, Video)</li>
        <li>Easy Access to Online Services</li>
    </ul>

    <h3>Applications of the Internet</h3>

    <ul>
        <li>E-Mail Communication</li>
        <li>Online Education (E-Learning)</li>
        <li>Video Conferencing</li>
        <li>Online Banking</li>
        <li>E-Commerce (Online Shopping)</li>
        <li>Social Networking</li>
        <li>Entertainment and Streaming</li>
        <li>Cloud Computing</li>
        <li>Government Services</li>
        <li>Online Gaming</li>
    </ul>

    <h3>Advantages of the Internet</h3>

    <ul>
        <li>Instant communication across the world.</li>
        <li>Easy access to information and knowledge.</li>
        <li>Supports online education and remote learning.</li>
        <li>Provides online business and banking facilities.</li>
        <li>Enables remote work and collaboration.</li>
        <li>Saves time and cost.</li>
    </ul>

    <h3>Disadvantages of the Internet</h3>

    <ul>
        <li>Cybercrime and hacking.</li>
        <li>Privacy and security issues.</li>
        <li>Spread of fake news and misinformation.</li>
        <li>Internet addiction.</li>
        <li>Virus and malware attacks.</li>
    </ul>

    <h3>Real-Life Examples</h3>

    <ul>
        <li>Watching videos on YouTube.</li>
        <li>Searching information using Google.</li>
        <li>Sending messages through WhatsApp.</li>
        <li>Attending online classes using Google Meet or Zoom.</li>
        <li>Shopping on Amazon or Flipkart.</li>
        <li>Using online banking applications.</li>
    </ul>

    <h3>Class Summary</h3>

    <p>
        In today's lecture, we learned the meaning of the Internet, its definitions, why it is called the
        <strong>Network of Networks</strong>, its basic components, features, applications, advantages,
        disadvantages, and real-life uses. The Internet has transformed the way people communicate, learn,
        work, and access information, making it one of the most important technologies in the modern world.
    </p>

</div>
`;

const cableSatelliteContent = `
<h4 id="notes_title">Cable Connection & Satellite Connection</h4>

<div class="notes_text" id="notes_text">

    <p>
        To use the Internet, a user must connect their computer or mobile device to an Internet Service Provider (ISP).
        There are different methods of connecting to the Internet, such as Telephone, Cable, Fiber Optic, Wireless,
        and Satellite connections. In this lecture, we will study <strong>Cable Connection</strong> and
        <strong>Satellite Connection</strong> in detail.
    </p>

    <h3>What is a Cable Connection?</h3>

    <p>
        A <strong>Cable Internet Connection</strong> is a type of broadband Internet connection that uses
        <strong>coaxial cables</strong> to transmit data. These are the same cables that are commonly used for
        cable television (Cable TV). Cable Internet provides high-speed Internet access and is one of the most
        widely used Internet connection methods in homes and offices.
    </p>

    <h3>How Does Cable Internet Work?</h3>

    <p>
        In a cable connection, the user's computer or Wi-Fi router is connected to a <strong>Cable Modem</strong>.
        The cable modem is connected through a coaxial cable to the cable service provider's network.
        The service provider then connects the user to the Internet through high-speed backbone networks.
    </p>

    <h3>Components Required</h3>

    <ul>
        <li>Computer, Laptop, or Mobile Device</li>
        <li>Cable Modem</li>
        <li>Wi-Fi Router (Optional)</li>
        <li>Coaxial Cable</li>
        <li>Internet Service Provider (ISP)</li>
    </ul>

    <h3>Advantages of Cable Connection</h3>

    <ul>
        <li>High-speed Internet access.</li>
        <li>Suitable for HD video streaming and online gaming.</li>
        <li>Always connected (No need to dial every time).</li>
        <li>Supports multiple devices through Wi-Fi.</li>
        <li>More reliable than traditional dial-up connections.</li>
    </ul>

    <h3>Disadvantages of Cable Connection</h3>

    <ul>
        <li>Internet speed may decrease during peak usage hours because bandwidth is shared among nearby users.</li>
        <li>Available only in areas where cable infrastructure exists.</li>
        <li>Installation cost may be higher than telephone connections.</li>
    </ul>

    <h3>Applications of Cable Internet</h3>

    <ul>
        <li>Home Internet</li>
        <li>Online Classes</li>
        <li>Video Streaming (YouTube, Netflix)</li>
        <li>Online Gaming</li>
        <li>Office Internet</li>
        <li>Video Conferencing</li>
    </ul>

    <hr>

    <h3>What is a Satellite Connection?</h3>

    <p>
        A <strong>Satellite Internet Connection</strong> is a type of wireless Internet connection that uses
        communication satellites orbiting the Earth to provide Internet access. It is mainly used in remote,
        rural, mountainous, desert, and island areas where cable or fiber Internet is not available.
    </p>

    <h3>How Does Satellite Internet Work?</h3>

    <p>
        In a satellite connection, the user's computer is connected to a <strong>Satellite Modem</strong>, which
        communicates with a <strong>Satellite Dish</strong> installed outside the building.
        The satellite dish sends signals to a communication satellite in space. The satellite forwards these
        signals to the ISP's ground station, which then connects the user to the Internet.
    </p>

    <h3>Components Required</h3>

    <ul>
        <li>Computer, Laptop, or Mobile Device</li>
        <li>Satellite Dish Antenna</li>
        <li>Satellite Modem</li>
        <li>Wi-Fi Router (Optional)</li>
        <li>Communication Satellite</li>
        <li>Ground Station</li>
        <li>Internet Service Provider (ISP)</li>
    </ul>

    <h3>Advantages of Satellite Connection</h3>

    <ul>
        <li>Available in remote and rural areas.</li>
        <li>Does not require telephone or cable infrastructure.</li>
        <li>Provides Internet access where other technologies are unavailable.</li>
        <li>Useful during natural disasters when terrestrial networks fail.</li>
    </ul>

    <h3>Disadvantages of Satellite Connection</h3>

    <ul>
        <li>Higher installation and equipment cost.</li>
        <li>Higher latency due to long-distance communication with satellites.</li>
        <li>Weather conditions such as heavy rain and storms may affect signal quality.</li>
        <li>Usually slower and more expensive than fiber or cable Internet.</li>
    </ul>

    <h3>Applications of Satellite Internet</h3>

    <ul>
        <li>Remote Villages</li>
        <li>Ships and Marine Communication</li>
        <li>Airplanes</li>
        <li>Military Communication</li>
        <li>Disaster Recovery Operations</li>
        <li>Research Stations</li>
    </ul>

    <h3>Difference Between Cable and Satellite Connection</h3>

    <table class="notes-table" border="1" cellpadding="8" cellspacing="0">
        <tr>
            <th>Cable Connection</th>
            <th>Satellite Connection</th>
        </tr>
        <tr>
            <td>Uses Coaxial Cable.</td>
            <td>Uses Communication Satellites.</td>
        </tr>
        <tr>
            <td>Provides high-speed Internet.</td>
            <td>Generally slower due to higher latency.</td>
        </tr>
        <tr>
            <td>Less affected by weather.</td>
            <td>Weather may affect signal quality.</td>
        </tr>
        <tr>
            <td>Suitable for cities and towns.</td>
            <td>Suitable for remote and rural areas.</td>
        </tr>
        <tr>
            <td>Lower latency.</td>
            <td>Higher latency.</td>
        </tr>
        <tr>
            <td>Requires cable infrastructure.</td>
            <td>No cable infrastructure required.</td>
        </tr>
    </table>

    <h3>Class Summary</h3>

    <p>
        In today's lecture, we learned about two important Internet connection methods:
        <strong>Cable Connection</strong> and <strong>Satellite Connection</strong>.
        We studied their working principles, required components, advantages, disadvantages,
        applications, and differences. Cable Internet is commonly used in homes and offices
        because of its high speed, while Satellite Internet is mainly used in remote areas
        where cable or fiber connections are not available.
    </p>

</div>
`;

