        java.setBounds(50,40,100,30);

        python.setBounds(50,80,100,30);

        cpp.setBounds(50,120,100,30);

        frame.add(java);

        frame.add(python);

        frame.add(cpp);

        frame.setLayout(null);

        frame.setSize(300,250);

