const menusToolbarsContent = `

<h3>Menus & Toolbars in Java Swing</h3>

<p>
In the previous lecture, we learned about <b>JSplitPane</b>, which divides a window into two resizable sections.
</p>

<p>
Now we will learn about <b>Menus</b> and <b>Toolbars</b>, which are essential parts of almost every desktop application.
</p>

<p>
Applications like <b>Notepad</b>, <b>MS Word</b>, <b>Paint</b>, <b>Eclipse</b>, and <b>NetBeans</b> all use menus and toolbars to provide quick access to different commands.
</p>

<hr>

<h3>What Will We Learn?</h3>

<ul>

<li>Introduction to JMenuBar</li>

<li>Introduction to JMenu</li>

<li>Introduction to JMenuItem</li>

<li>Introduction to JToolBar</li>

<li>Separators</li>

<li>Icons in Menu</li>

<li>Keyboard Shortcuts</li>

<li>Mnemonics</li>

<li>Complete Programs</li>

<li>Real-Life Applications</li>

<li>Interview Questions</li>

</ul>

<hr>

<h3>What is a Menu?</h3>

<p>
A <b>Menu</b> is a list of commands displayed at the top of a window.
It groups similar commands together, making applications easy to use.
</p>

<p>
For example, the <b>File</b> menu contains commands like New, Open, Save, and Exit.
</p>

<hr>

<h3>Definition</h3>

<p>
A <b>Menu</b> is a collection of related commands organized under a common heading.
</p>

<hr>

<h3>What is JMenuBar?</h3>

<p>
<b>JMenuBar</b> is the container that holds one or more menus.
It appears at the top of the application window.
</p>

<hr>

<h3>Example</h3>

<pre class="notes_text_pre">

------------------------------------------------

 File   Edit   View   Help

------------------------------------------------

</pre>

<hr>

<h3>What is JMenu?</h3>

<p>
<b>JMenu</b> represents an individual menu such as File, Edit, View, or Help.
Each JMenu contains one or more menu items.
</p>

<hr>

<h3>Example</h3>

<pre class="notes_text_pre">

File

    New

    Open

    Save

    Exit

</pre>

<hr>

<h3>What is JMenuItem?</h3>

<p>
<b>JMenuItem</b> represents an individual command inside a menu.
When the user clicks a menu item, an action is performed.
</p>

<hr>

<h3>Real-Life Examples</h3>

<ul>

<li>New File</li>

<li>Open File</li>

<li>Save File</li>

<li>Print</li>

<li>Exit</li>

</ul>

<hr>

<h3>What is JToolBar?</h3>

<p>
<b>JToolBar</b> is a container that holds buttons or other controls for quick access to frequently used commands.
</p>

<p>
Instead of opening a menu every time, users can simply click a toolbar button.
</p>

<hr>

<h3>Real-Life Example</h3>

<pre class="notes_text_pre">

-------------------------------------------------------

📄  📂  💾  ✂️  📋  📌

-------------------------------------------------------

</pre>

<hr>

<h3>Package</h3>

<pre class="notes_text_pre"><code class="language-java">
import javax.swing.*;
</code></pre>

<hr>

<h3>Creating a Menu Bar</h3>

<pre class="notes_text_pre"><code class="language-java">
JMenuBar menuBar =
new JMenuBar();
</code></pre>

<hr>

<h3>Creating Menus</h3>

<pre class="notes_text_pre"><code class="language-java">
JMenu file =
new JMenu("File");

JMenu edit =
new JMenu("Edit");

JMenu help =
new JMenu("Help");
</code></pre>

<hr>

<h3>Creating Menu Items</h3>

<pre class="notes_text_pre"><code class="language-java">
JMenuItem newItem =
new JMenuItem("New");

JMenuItem openItem =
new JMenuItem("Open");

JMenuItem saveItem =
new JMenuItem("Save");

JMenuItem exitItem =
new JMenuItem("Exit");
</code></pre>

<hr>

<h3>Adding Menu Items</h3>

<pre class="notes_text_pre"><code class="language-java">
file.add(newItem);

file.add(openItem);

file.add(saveItem);

file.addSeparator();

file.add(exitItem);
</code></pre>

<hr>

<h3>Adding Menus to Menu Bar</h3>

<pre class="notes_text_pre"><code class="language-java">
menuBar.add(file);

menuBar.add(edit);

menuBar.add(help);
</code></pre>

<hr>

<h3>Adding Menu Bar to JFrame</h3>

<pre class="notes_text_pre"><code class="language-java">
frame.setJMenuBar(menuBar);
</code></pre>

<hr>

<h3>Creating a Toolbar</h3>

<pre class="notes_text_pre"><code class="language-java">
JToolBar toolBar =
new JToolBar();
</code></pre>

<hr>

<h3>Adding Buttons to Toolbar</h3>

<pre class="notes_text_pre"><code class="language-java">
JButton newBtn =
new JButton("New");

JButton openBtn =
new JButton("Open");

JButton saveBtn =
new JButton("Save");

toolBar.add(newBtn);

toolBar.add(openBtn);

toolBar.add(saveBtn);
</code></pre>

<hr>

<h3>Keyboard Shortcut (Accelerator)</h3>

<p>
An accelerator allows users to execute a command using the keyboard.
</p>

<pre class="notes_text_pre"><code class="language-java">
newItem.setAccelerator(
KeyStroke.getKeyStroke(
"control N"));
</code></pre>

<p>
Now pressing <b>Ctrl + N</b> will activate the "New" menu item.
</p>

<hr>

<h3>Mnemonic Key</h3>

<p>
A mnemonic allows users to open menus using the <b>Alt</b> key.
</p>

<pre class="notes_text_pre"><code class="language-java">
file.setMnemonic('F');
</code></pre>

<p>
Pressing <b>Alt + F</b> opens the File menu.
</p>

<hr>

<h3>Complete Program</h3>

<pre class="notes_text_pre"><code class="language-java">
import javax.swing.*;

public class MenuDemo
{
    public static void main(String args[])
    {
        JFrame frame =
        new JFrame("Menu Demo");

        JMenuBar menuBar =
        new JMenuBar();

        JMenu file =
        new JMenu("File");

        JMenuItem newItem =
        new JMenuItem("New");

        JMenuItem openItem =
        new JMenuItem("Open");

        JMenuItem saveItem =
        new JMenuItem("Save");

        JMenuItem exitItem =
        new JMenuItem("Exit");

        file.add(newItem);

        file.add(openItem);

        file.add(saveItem);

        file.addSeparator();

        file.add(exitItem);

        menuBar.add(file);

        frame.setJMenuBar(menuBar);

        JToolBar toolBar =
        new JToolBar();

        toolBar.add(
        new JButton("New"));

        toolBar.add(
        new JButton("Open"));

        toolBar.add(
        new JButton("Save"));

        frame.add(toolBar);

        frame.setSize(500,300);

        frame.setDefaultCloseOperation(
        JFrame.EXIT_ON_CLOSE);

        frame.setVisible(true);
    }
}
</code></pre>

<hr>

<h3>Output</h3>

<pre class="notes_text_pre">

------------------------------------------------------

 File   Edit   Help

------------------------------------------------------

 New   Open   Save

------------------------------------------------------


</pre>

<hr>

<h3>Important Classes</h3>

<table class="notes-table">

<tr>
<th>Class</th>
<th>Purpose</th>
</tr>

<tr>
<td>JMenuBar</td>
<td>Holds all menus.</td>
</tr>

<tr>
<td>JMenu</td>
<td>Represents one menu.</td>
</tr>

<tr>
<td>JMenuItem</td>
<td>Represents one command.</td>
</tr>

<tr>
<td>JToolBar</td>
<td>Holds shortcut buttons.</td>
</tr>

<tr>
<td>KeyStroke</td>
<td>Creates keyboard shortcuts.</td>
</tr>

</table>

<hr>

<h3>Advantages</h3>

<ul>

<li>Provides organized navigation.</li>

<li>Makes applications easy to use.</li>

<li>Offers quick access through toolbar buttons.</li>

<li>Supports keyboard shortcuts.</li>

<li>Professional desktop application interface.</li>

</ul>

<hr>

<h3>Applications</h3>

<table class="notes-table">

<tr>
<th>Software</th>
<th>Menus & Toolbars</th>
</tr>

<tr>
<td>Notepad</td>
<td>File, Edit, Format</td>
</tr>

<tr>
<td>MS Word</td>
<td>Home, Insert, Review</td>
</tr>

<tr>
<td>Paint</td>
<td>Drawing Tools</td>
</tr>

<tr>
<td>Eclipse IDE</td>
<td>File, Edit, Run</td>
</tr>

<tr>
<td>NetBeans</td>
<td>Build, Debug, Window</td>
</tr>

</table>

<hr>

<h3>JMenu vs JMenuItem</h3>

<table class="notes-table">

<tr>
<th>JMenu</th>
<th>JMenuItem</th>
</tr>

<tr>
<td>Represents a menu.</td>
<td>Represents a command.</td>
</tr>

<tr>
<td>Contains menu items.</td>
<td>Cannot contain other menu items.</td>
</tr>

<tr>
<td>Example: File</td>
<td>Example: Open</td>
</tr>

</table>

<hr>

<h3>Classroom Summary</h3>

<ul>

<li>JMenuBar holds all menus.</li>

<li>JMenu represents a menu like File or Edit.</li>

<li>JMenuItem represents commands like Open or Save.</li>

<li>JToolBar provides quick-access buttons.</li>

<li>setJMenuBar() attaches the menu bar to a JFrame.</li>

<li>Accelerators create keyboard shortcuts.</li>

<li>Mnemonics allow menu access using the Alt key.</li>

</ul>

<hr>

<h3>Interview Questions</h3>

<ol>

<li>What is JMenuBar?</li>

<li>What is the difference between JMenu and JMenuItem?</li>

<li>What is JToolBar?</li>

<li>How do you add a menu bar to a JFrame?</li>

<li>What is the purpose of addSeparator()?</li>

<li>What is an accelerator?</li>

<li>What is a mnemonic key?</li>

<li>Name five real-life applications that use menus and toolbars.</li>

</ol>

`;

const dialogBoxesContent = `

<h3>JOptionPane & Dialog Boxes</h3>

<p>
In the previous lecture, we learned about <b>Menus & Toolbars</b>, which provide an organized way to access commands in a Swing application.
</p>

<p>
Now we will learn about <b>JOptionPane</b>, one of the most useful Swing classes for displaying dialog boxes.
</p>

<p>
Dialog boxes are small windows that interact with the user by displaying messages, asking questions, accepting input, or confirming an action.
</p>

<p>
Almost every desktop application uses dialog boxes. For example, when you try to close a document without saving, a confirmation dialog appears asking whether you want to save your changes.
</p>

<hr>

<h3>What Will We Learn?</h3>

<ul>

<li>Introduction to JOptionPane</li>

<li>What is a Dialog Box?</li>

<li>Types of Dialog Boxes</li>

<li>Message Dialog</li>

<li>Input Dialog</li>

<li>Confirm Dialog</li>

<li>Option Dialog</li>

<li>Message Types</li>

<li>Complete Programs</li>

<li>Real-Life Applications</li>

<li>Interview Questions</li>

</ul>

<hr>

<h3>What is a Dialog Box?</h3>

<p>
A <b>Dialog Box</b> is a small pop-up window that communicates with the user.
It displays information, requests input, asks for confirmation, or allows the user to choose from different options.
</p>

<hr>

<h3>Definition</h3>

<p>
A <b>Dialog Box</b> is a temporary window used to exchange information between the application and the user.
</p>

<hr>

<h3>What is JOptionPane?</h3>

<p>
<b>JOptionPane</b> is a Swing utility class that provides ready-made dialog boxes.
</p>

<p>
Instead of designing your own dialog window, you can simply call one of its methods to display professional-looking dialog boxes.
</p>

<hr>

<h3>Real-Life Examples</h3>

<ul>

<li>Login Success Message</li>

<li>Delete Confirmation</li>

<li>Enter Student Name</li>

<li>Password Incorrect</li>

<li>Application Exit Confirmation</li>

<li>Warning Before Deleting Data</li>

</ul>

<hr>

<h3>Package</h3>

<pre class="notes_text_pre"><code class="language-java">
import javax.swing.*;
</code></pre>

<hr>

<h3>Types of Dialog Boxes</h3>

<table class="notes-table">

<tr>
<th>Dialog</th>
<th>Purpose</th>
</tr>

<tr>
<td>showMessageDialog()</td>
<td>Displays a message.</td>
</tr>

<tr>
<td>showInputDialog()</td>
<td>Accepts user input.</td>
</tr>

<tr>
<td>showConfirmDialog()</td>
<td>Asks Yes/No/Cancel questions.</td>
</tr>

<tr>
<td>showOptionDialog()</td>
<td>Displays custom buttons.</td>
</tr>

</table>

<hr>

<h3>1. Message Dialog</h3>

<p>
A Message Dialog displays information to the user.
It does not require any input.
</p>

<pre class="notes_text_pre"><code class="language-java">
JOptionPane.showMessageDialog(
null,
"Welcome Students!");
</code></pre>

<hr>

<h3>Output</h3>

<pre class="notes_text_pre">

----------------------------

Information

----------------------------

Welcome Students!

          [ OK ]

----------------------------

</pre>

<hr>

<h3>2. Input Dialog</h3>

<p>
An Input Dialog asks the user to enter a value.
</p>

<pre class="notes_text_pre"><code class="language-java">
String name =
JOptionPane.showInputDialog(
"Enter Your Name");
</code></pre>

<hr>

<h3>Output</h3>

<pre class="notes_text_pre">

----------------------------

Enter Your Name

_____________________

        [ OK ]

----------------------------

</pre>

<hr>

<h3>3. Confirm Dialog</h3>

<p>
A Confirm Dialog asks the user to confirm an action.
</p>

<pre class="notes_text_pre"><code class="language-java">
int choice =
JOptionPane.showConfirmDialog(
null,
"Do you want to exit?");
</code></pre>

<hr>

<h3>Output</h3>

<pre class="notes_text_pre">

Do you want to exit?

[ YES ] [ NO ] [ CANCEL ]

</pre>

<hr>

<h3>Understanding the Return Value</h3>

<table class="notes-table">

<tr>
<th>Button</th>
<th>Returned Value</th>
</tr>

<tr>
<td>Yes</td>
<td>JOptionPane.YES_OPTION</td>
</tr>

<tr>
<td>No</td>
<td>JOptionPane.NO_OPTION</td>
</tr>

<tr>
<td>Cancel</td>
<td>JOptionPane.CANCEL_OPTION</td>
</tr>

</table>

<hr>

<h3>Checking User Choice</h3>

<pre class="notes_text_pre"><code class="language-java">
int choice =
JOptionPane.showConfirmDialog(
null,
"Exit Application?");

if(choice ==
JOptionPane.YES_OPTION)
{
    System.exit(0);
}
</code></pre>

<hr>

<h3>4. Option Dialog</h3>

<p>
Option Dialog allows us to create our own custom buttons.
</p>

<pre class="notes_text_pre"><code class="language-java">
String options[] =
{"Java","Python","C++"};

JOptionPane.showOptionDialog(
null,
"Choose Language",
"Selection",
JOptionPane.DEFAULT_OPTION,
JOptionPane.INFORMATION_MESSAGE,
null,
options,
options[0]);
</code></pre>

<hr>

<h3>Message Types</h3>

<table class="notes-table">

<tr>
<th>Constant</th>
<th>Description</th>
</tr>

<tr>
<td>ERROR_MESSAGE</td>
<td>Shows an error icon.</td>
</tr>

<tr>
<td>WARNING_MESSAGE</td>
<td>Shows a warning icon.</td>
</tr>

<tr>
<td>INFORMATION_MESSAGE</td>
<td>Shows an information icon.</td>
</tr>

<tr>
<td>QUESTION_MESSAGE</td>
<td>Shows a question icon.</td>
</tr>

<tr>
<td>PLAIN_MESSAGE</td>
<td>Displays no icon.</td>
</tr>

</table>

<hr>

<h3>Information Dialog Example</h3>

<pre class="notes_text_pre"><code class="language-java">
JOptionPane.showMessageDialog(
null,
"Student Saved Successfully!",
"Information",
JOptionPane.INFORMATION_MESSAGE);
</code></pre>

<hr>

<h3>Error Dialog Example</h3>

<pre class="notes_text_pre"><code class="language-java">
JOptionPane.showMessageDialog(
null,
"Invalid Password!",
"Error",
JOptionPane.ERROR_MESSAGE);
</code></pre>

<hr>

<h3>Warning Dialog Example</h3>

<pre class="notes_text_pre"><code class="language-java">
JOptionPane.showMessageDialog(
null,
"Please Save Your Work!",
"Warning",
JOptionPane.WARNING_MESSAGE);
</code></pre>

<hr>

<h3>Question Dialog Example</h3>

<pre class="notes_text_pre"><code class="language-java">
JOptionPane.showMessageDialog(
null,
"Continue?",
"Question",
JOptionPane.QUESTION_MESSAGE);
</code></pre>

<hr>

<h3>Complete Program</h3>

<pre class="notes_text_pre"><code class="language-java">
import javax.swing.*;

public class JOptionPaneDemo
{
    public static void main(String args[])
    {
        JOptionPane.showMessageDialog(
        null,
        "Welcome to Java Swing!");

        String name =
        JOptionPane.showInputDialog(
        "Enter Your Name");

        JOptionPane.showMessageDialog(
        null,
        "Welcome " + name);

        int choice =
        JOptionPane.showConfirmDialog(
        null,
        "Do you want to continue?");

        if(choice ==
        JOptionPane.YES_OPTION)
        {
            JOptionPane.showMessageDialog(
            null,
            "Thank You!");
        }
        else
        {
            JOptionPane.showMessageDialog(
            null,
            "Application Closed.");
        }
    }
}
</code></pre>

<hr>

<h3>Advantages</h3>

<ul>

<li>Easy to use.</li>

<li>No need to design a custom dialog window.</li>

<li>Provides professional-looking pop-up windows.</li>

<li>Supports user input and confirmation.</li>

<li>Includes built-in icons for different message types.</li>

</ul>

<hr>

<h3>Applications</h3>

<table class="notes-table">

<tr>
<th>Application</th>
<th>Purpose</th>
</tr>

<tr>
<td>Login System</td>
<td>Invalid Username or Password</td>
</tr>

<tr>
<td>Student Management</td>
<td>Record Saved Successfully</td>
</tr>

<tr>
<td>Banking Software</td>
<td>Transaction Confirmation</td>
</tr>

<tr>
<td>Hospital System</td>
<td>Delete Patient Record</td>
</tr>

<tr>
<td>Text Editor</td>
<td>Save Before Exit</td>
</tr>

</table>

<hr>

<h3>JOptionPane vs JFrame</h3>

<table class="notes-table">

<tr>
<th>JOptionPane</th>
<th>JFrame</th>
</tr>

<tr>
<td>Displays temporary dialog boxes.</td>
<td>Creates the main application window.</td>
</tr>

<tr>
<td>Built-in utility class.</td>
<td>Top-level Swing container.</td>
</tr>

<tr>
<td>Requires very little code.</td>
<td>Requires manual design of components.</td>
</tr>

</table>

<hr>

<h3>Classroom Summary</h3>

<ul>

<li>JOptionPane is used to display dialog boxes.</li>

<li>showMessageDialog() displays information.</li>

<li>showInputDialog() accepts user input.</li>

<li>showConfirmDialog() asks for confirmation.</li>

<li>showOptionDialog() creates custom options.</li>

<li>Different message types display different icons.</li>

<li>JOptionPane is widely used in desktop applications.</li>

</ul>

<hr>

<h3>Interview Questions</h3>

<ol>

<li>What is JOptionPane?</li>

<li>What is the purpose of a dialog box?</li>

<li>What is the difference between showMessageDialog() and showInputDialog()?</li>

<li>What does showConfirmDialog() return?</li>

<li>Name the five message types available in JOptionPane.</li>

<li>When should you use showOptionDialog()?</li>

<li>What is the difference between JOptionPane and JFrame?</li>

<li>Give five real-life applications of JOptionPane.</li>

</ol>

`;


const windowsContent = `

<h3>Window Events in Java Swing</h3>

<p>
In the previous lecture, we learned about <b>JOptionPane & Dialog Boxes</b>, which are used to display messages, accept input, and confirm user actions.
</p>

<p>
Now we will learn about <b>Window Events</b>. Window events occur whenever the user interacts with an application window, such as opening, closing, minimizing, maximizing, or activating it.
</p>

<p>
Window events are commonly used to save data before closing an application, display welcome messages when a window opens, or release resources when the application exits.
</p>

<hr>

<h3>What Will We Learn?</h3>

<ul>

<li>Introduction to Window Events</li>

<li>WindowListener Interface</li>

<li>WindowAdapter Class</li>

<li>Types of Window Events</li>

<li>Important Methods</li>

<li>Window Closing Example</li>

<li>WindowAdapter Example</li>

<li>Complete Programs</li>

<li>Real-Life Applications</li>

<li>Interview Questions</li>

</ul>

<hr>

<h3>What are Window Events?</h3>

<p>
<b>Window Events</b> are events generated when the user performs actions on a window.
These actions include opening, closing, minimizing, restoring, activating, or deactivating the window.
</p>

<hr>

<h3>Definition</h3>

<p>
<b>Window Events</b> are generated whenever the state of a window changes because of user interaction or program execution.
</p>

<hr>

<h3>Real-Life Examples</h3>

<ul>

<li>Display a welcome message when the application starts.</li>

<li>Ask the user to save work before closing.</li>

<li>Release database connections while exiting.</li>

<li>Pause a video when the window loses focus.</li>

<li>Refresh data when the window becomes active.</li>

</ul>

<hr>

<h3>Package</h3>

<pre class="notes_text_pre"><code class="language-java">
import java.awt.event.*;

import javax.swing.*;
</code></pre>

<hr>

<h3>What is WindowListener?</h3>

<p>
<b>WindowListener</b> is an interface that receives all window-related events.
To use it, a class must implement all its methods.
</p>

<hr>

<h3>WindowListener Syntax</h3>

<pre class="notes_text_pre"><code class="language-java">
public class Demo
implements WindowListener
{

}
</code></pre>

<hr>

<h3>Methods of WindowListener</h3>

<table class="notes-table">

<tr>
<th>Method</th>
<th>Purpose</th>
</tr>

<tr>
<td>windowOpened()</td>
<td>Called when the window opens.</td>
</tr>

<tr>
<td>windowClosing()</td>
<td>Called before the window closes.</td>
</tr>

<tr>
<td>windowClosed()</td>
<td>Called after the window closes.</td>
</tr>

<tr>
<td>windowIconified()</td>
<td>Called when the window is minimized.</td>
</tr>

<tr>
<td>windowDeiconified()</td>
<td>Called when the window is restored.</td>
</tr>

<tr>
<td>windowActivated()</td>
<td>Called when the window becomes active.</td>
</tr>

<tr>
<td>windowDeactivated()</td>
<td>Called when the window loses focus.</td>
</tr>

</table>

<hr>

<h3>Problem with WindowListener</h3>

<p>
The WindowListener interface contains seven methods.
Even if we need only one method, we must implement all seven methods.
This makes the code lengthy and unnecessary.
</p>

<hr>

<h3>What is WindowAdapter?</h3>

<p>
<b>WindowAdapter</b> is a helper class that provides empty implementations of all WindowListener methods.
</p>

<p>
Instead of implementing every method, we can extend WindowAdapter and override only the required method.
</p>

<hr>

<h3>WindowAdapter Syntax</h3>

<pre class="notes_text_pre"><code class="language-java">
frame.addWindowListener(
new WindowAdapter()
{
    public void windowClosing(
    WindowEvent e)
    {

    }
});
</code></pre>

<hr>

<h3>Window Closing Example</h3>

<pre class="notes_text_pre"><code class="language-java">
frame.addWindowListener(
new WindowAdapter()
{
    public void windowClosing(
    WindowEvent e)
    {
        JOptionPane.showMessageDialog(
        null,
        "Closing Application...");
    }
});
</code></pre>

<hr>

<h3>Complete Program Using WindowListener</h3>

<pre class="notes_text_pre"><code class="language-java">
import javax.swing.*;
import java.awt.event.*;

public class WindowListenerDemo
implements WindowListener
{
    JFrame frame;

    WindowListenerDemo()
    {
        frame = new JFrame(
        "Window Events");

        frame.setSize(400,250);

        frame.addWindowListener(this);

        frame.setVisible(true);
    }

    public void windowOpened(WindowEvent e)
    {
        System.out.println(
        "Window Opened");
    }

    public void windowClosing(WindowEvent e)
    {
        System.out.println(
        "Window Closing");

        System.exit(0);
    }

    public void windowClosed(WindowEvent e){}

    public void windowIconified(WindowEvent e){}

    public void windowDeiconified(WindowEvent e){}

    public void windowActivated(WindowEvent e){}

    public void windowDeactivated(WindowEvent e){}

    public static void main(String args[])
    {
        new WindowListenerDemo();
    }
}
</code></pre>

<hr>

<h3>Complete Program Using WindowAdapter</h3>

<pre class="notes_text_pre"><code class="language-java">
import javax.swing.*;
import java.awt.event.*;

public class WindowAdapterDemo
{
    public static void main(String args[])
    {
        JFrame frame =
        new JFrame("WindowAdapter");

        frame.setSize(400,250);

        frame.addWindowListener(
        new WindowAdapter()
        {
            public void windowClosing(
            WindowEvent e)
            {
                JOptionPane.showMessageDialog(
                null,
                "Thank You!");

                System.exit(0);
            }
        });

        frame.setVisible(true);
    }
}
</code></pre>

<hr>

<h3>Output</h3>

<pre class="notes_text_pre">

-------------------------------

WindowAdapter Demo

-------------------------------

(User clicks Close button)

-------------------------------

Thank You!

        [ OK ]

-------------------------------

Application Closed

</pre>

<hr>

<h3>WindowListener vs WindowAdapter</h3>

<table class="notes-table">

<tr>
<th>WindowListener</th>
<th>WindowAdapter</th>
</tr>

<tr>
<td>Interface</td>
<td>Adapter Class</td>
</tr>

<tr>
<td>All methods must be implemented.</td>
<td>Only required methods are overridden.</td>
</tr>

<tr>
<td>More code.</td>
<td>Less code.</td>
</tr>

<tr>
<td>Rarely used directly.</td>
<td>Most commonly used in Swing.</td>
</tr>

</table>

<hr>

<h3>Applications of Window Events</h3>

<table class="notes-table">

<tr>
<th>Application</th>
<th>Purpose</th>
</tr>

<tr>
<td>Text Editor</td>
<td>Ask to save before exit.</td>
</tr>

<tr>
<td>Banking Software</td>
<td>Close user session safely.</td>
</tr>

<tr>
<td>Media Player</td>
<td>Pause video on minimize.</td>
</tr>

<tr>
<td>Game</td>
<td>Pause when window loses focus.</td>
</tr>

<tr>
<td>Database Application</td>
<td>Close database connection.</td>
</tr>

</table>

<hr>

<h3>Advantages</h3>

<ul>

<li>Responds to user actions on windows.</li>

<li>Helps manage application resources.</li>

<li>Improves application safety.</li>

<li>Provides better user experience.</li>

<li>Supports application lifecycle management.</li>

</ul>

<hr>

<h3>Classroom Summary</h3>

<ul>

<li>Window events occur when the state of a window changes.</li>

<li>WindowListener is an interface with seven methods.</li>

<li>WindowAdapter provides empty implementations.</li>

<li>WindowAdapter is easier and more commonly used.</li>

<li>windowClosing() is the most frequently used method.</li>

<li>Window events help manage application startup and shutdown.</li>

</ul>

<hr>

<h3>Interview Questions</h3>

<ol>

<li>What are Window Events?</li>

<li>What is the purpose of WindowListener?</li>

<li>How many methods does WindowListener contain?</li>

<li>What is WindowAdapter?</li>

<li>Why is WindowAdapter preferred over WindowListener?</li>

<li>Which method is called before a window closes?</li>

<li>What is the difference between windowClosing() and windowClosed()?</li>

<li>Give five real-life applications of Window Events.</li>

</ol>

`;

